+/** The best supported language in an Accept-Language header (q-values, region tags), else `fallback`. */
+export function pickLanguage(header, fallback = "en") {
+  const ranked = String(header ?? "")
+    .split(",")
+    .map((part, index) => {
+      const [tag, ...attrs] = part.trim().split(";");
+      const q = attrs.map((a) => /^\s*q\s*=\s*([\d.]+)\s*$/i.exec(a)).find(Boolean);
+      return { lang: tag.trim().toLowerCase().split("-")[0], q: q ? Number(q[1]) : 1, index };
+    })
+    .filter((c) => LANGUAGES.includes(c.lang) && c.q > 0)
+    .sort((a, b) => b.q - a.q || a.index - b.index);
+  return ranked.length ? ranked[0].lang : fallback;
+}
